(function(root){
 'use strict';let data,esc,link,sourceLink;
 function configure(o){({data,esc,link,sourceLink}=o);}
 function page(p){
  const guides=data.toolGuides,chosen=guides.find(g=>g.id===p.get('framework'));
  return `<div class="intro"><div class="eyebrow">ОБУЧИТЬ → УВИДЕТЬ → СРАВНИТЬ</div><h1>Инструменты обучения.</h1><p>Lightning организует цикл, TensorBoard показывает его ход, MLflow сохраняет контекст и результаты экспериментов. Изучайте их по отдельности, затем соедините в одном небольшом проекте.</p></div><div class="callout"><strong>Дополнение к курсу по официальной документации</strong>Это инженерная практика вне ноутбуков МФТИ. API сверены 24 октября 2026. Примеры рассчитаны на Python 3.12 и PyTorch; код исполняется в вашей Python-среде, сайт хранит теорию и проверяет ответы.</div><nav class="tabs" aria-label="Инструменты"><a href="#tools" class="${!chosen?'active':''}">Все три</a>${guides.map(g=>`<a href="${link('tools',{framework:g.id})}" class="${chosen?.id===g.id?'active':''}">${esc(g.title)}</a>`).join('')}</nav><div class="tools-flow" aria-label="Как инструменты соединяются"><div><strong>1 · PyTorch</strong><span>Данные, forward, loss</span></div><span aria-hidden="true">→</span><div><strong>2 · Lightning</strong><span>Цикл, optimizer, checkpoint</span></div><span aria-hidden="true">→</span><div><strong>3 · Наблюдение</strong><span>TensorBoard: графики<br>MLflow: run, конфиг, модель</span></div></div>${(chosen?[chosen]:guides).map(guide).join('')}<section class="panel"><h2>Как закреплять материал</h2><ol><li>Прочитайте тему и предскажите результат короткой ячейки, не открывая ответ.</li><li>Запустите пример в Python, поменяйте один параметр и объясните изменение.</li><li>Ответьте в тренировке. Развёрнутый ответ оцените по эталону и трём критериям.</li><li>Соберите мини-проект, затем вернитесь к ошибкам через «Мой прогресс».</li></ol><a class="btn" href="${link('practice',{collection:'tooling',count:15})}">Смешанная тренировка по инструментам →</a></section>`;
 }
 function guide(g){
  const qs=data.questions.filter(q=>q.framework===g.id),cards=data.codeCards.filter(c=>c.framework===g.id);
  return `<section class="panel tool-guide" id="guide-${g.id}"><div class="eyebrow">${g.topics.length} ТЕМ · ${qs.length} ВОПРОСОВ · ${cards.length} ЯЧЕЕК КОДА</div><h2>${esc(g.title)}</h2><p class="lead">${esc(g.subtitle)}</p><h3>Перед началом</h3><p>${esc(g.prerequisite)}</p><details class="tool-setup"><summary>Среда и локальный просмотр результатов</summary><p>Сначала установите CPU или CUDA PyTorch по инструкции для своей системы. Эти команды выполняются в терминале Python-проекта.</p><pre tabindex="0"><code>${esc(g.install+'\n\n'+g.command)}</code></pre><p class="inline-note">Версии учебной проверки: Python 3.12, PyTorch 2.14.1, Lightning 2.6.6, TensorBoard 2.21.0, MLflow 3.17.2. В MLflow относительная training.db должна разрешаться в ту же папку в Python и в команде сервера.</p></details><h3>Порядок изучения</h3><ol class="tool-path">${g.topics.map(id=>{const t=data.topics.find(t=>t.id===id);return `<li><a href="${link('theory',{topic:id,lesson:t.lesson})}"><strong>${esc(t.title)}</strong></a><p>${esc(t.definition)}</p><a class="source-link" href="${link('practice',{collection:'tooling',topic:id,count:'all'})}">Проверить эту тему →</a></li>`;}).join('')}</ol><div class="callout"><strong>Мини-проект</strong>${esc(g.project)}</div><h3>Готов двигаться дальше, если…</h3><ul>${g.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions"><a class="btn" href="${link('practice',{collection:'tooling',framework:g.id,count:'all'})}">Все ${qs.length} вопросов →</a><a class="btn secondary" href="${link('code',{library:g.title})}">Короткие задачи на API →</a></div><h3>Читать в документации</h3>${g.docs.map(s=>`<p>${sourceLink({...s,checked:'2026-10-24'})}</p>`).join('')}</section>`;
 }
 root.CVTools={configure,page};
})(window);
